PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry max_reduce(
    .param .u64   input_ptr,
    .param .u64   output_ptr,
    .param .u32   batch,
    .param .u32   dim1,
    .param .u32   dim2
)
{
    // registers
    .reg .pred   %p;
    .reg .u32    %tid, %bid;
    .reg .u32    %batch, %dim1, %dim2;
    .reg .u64    %in_ptr, %out_ptr;
    .reg .u64    %base_offset, %elem_offset, %addr;
    .reg .f16    %max_val, %val;
    .reg .u32    %i;

    // -----------------------------------------------------------------
    // Load kernel parameters
    // -----------------------------------------------------------------
    ld.param.u64    %in_ptr,    [input_ptr];
    ld.param.u64    %out_ptr,   [output_ptr];
    ld.param.u32    %batch,     [batch];
    ld.param.u32    %dim1,      [dim1];
    ld.param.u32    %dim2,      [dim2];

    // -----------------------------------------------------------------
    // Thread / block indices
    // -----------------------------------------------------------------
    mov.u32 %tid, %tid.x;          // threadIdx.x  (0 .. dim2-1)
    mov.u32 %bid, %ctaid.x;        // blockIdx.x   (0 .. batch-1)

    // -----------------------------------------------------------------
    // Compute base byte offset for this batch (B * D1 * D2 * sizeof(half))
    // -----------------------------------------------------------------
    mul.lo.u32 %base_offset, %bid, %dim1;     // batch * D1
    mul.lo.u32 %base_offset, %base_offset, %dim2; // * D2
    mul.lo.u64 %base_offset, %base_offset, 2; // sizeof(half) = 2

    // -----------------------------------------------------------------
    // Load first element to initialise max (i = 0)
    // -----------------------------------------------------------------
    mul.lo.u32 %elem_offset, %tid, 2;          // column offset in bytes (i=0)
    add.u64 %addr, %in_ptr, %base_offset;
    add.u64 %addr, %addr, %elem_offset;
    ld.global.f16 %max_val, [%addr];

    // -----------------------------------------------------------------
    // Loop over remaining elements in dim1 (i = 1 .. D1-1)
    // -----------------------------------------------------------------
    mov.u32 %i, 1;
LOOP:
    setp.ge.u32 %p, %i, %dim1;
    @%p bra END_LOOP;

    // offset = i * D2 + tid   (in elements)
    mul.lo.u32 %elem_offset, %i, %dim2;
    add.u32 %elem_offset, %elem_offset, %tid;
    mul.lo.u64 %elem_offset, %elem_offset, 2; // convert to bytes

    add.u64 %addr, %in_ptr, %base_offset;
    add.u64 %addr, %addr, %elem_offset;
    ld.global.f16 %val, [%addr];

    // max_val = max(max_val, val)
    max.f16 %max_val, %max_val, %val;

    add.u32 %i, %i, 1;
    bra LOOP;
END_LOOP:

    // -----------------------------------------------------------------
    // Store result to output tensor (shape [B, D2])
    // -----------------------------------------------------------------
    // output offset = batch * D2 + tid  (in elements)
    mul.lo.u32 %elem_offset, %bid, %dim2;
    add.u32 %elem_offset, %elem_offset, %tid;
    mul.lo.u64 %elem_offset, %elem_offset, 2; // bytes

    add.u64 %addr, %out_ptr, %elem_offset;
    st.global.f16 [%addr], %max_val;

    ret;
}
'''
