# -----------------------------------------------------------------
class ModelNew:
    def __init__(self, dim: int):
        # The reference only supports reduction over dim=1 for the given shapes.
        # For any other dim we raise an error.
        if dim != 1:
            raise ValueError("ModelNew currently only supports dim=1 (max over middle dimension).")
        self.dim = dim
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x):
        """
        x : torch.Tensor of shape (B, D1, D2) and dtype torch.float16 on CUDA
        returns torch.Tensor of shape (B, D2) dtype torch.float16 on CUDA
        """
        if x.dtype != torch.float16:
            raise TypeError("Input tensor must be float16.")
        if not x.is_cuda:
            raise RuntimeError("Input tensor must be on CUDA device.")

        B, D1, D2 = x.shape
        out = torch.empty((B, D2), dtype=torch.float16, device=x.device)

        # Launch configuration: one block per batch, D2 threads per block
        grid = (B, 1, 1)
        block = (D2, 1, 1)

        args = [
            x.data_ptr(),
            out.data_ptr(),
            int(B),
            int(D1),
            int(D2)
        ]

        ptx_launch(self.module, "max_reduce", grid, block, args)
        return out
